const texto = $json.output?.[0]?.content?.[0]?.text || '';

let dados;

try {
  dados = JSON.parse(texto);
} catch (error) {
  return [
    {
      json: {
        erro: true,
        mensagem: 'Não foi possível converter o texto da IA para JSON.',
        detalhe: error.message,
        texto_original: texto
      }
    }
  ];
}

return [
  {
    json: {
      nome_original: dados.nome_original || '',
      nome_para_sql: dados.nome_para_sql || '',
      termos: Array.isArray(dados.termos) ? dados.termos : [],
      tem_nome: dados.tem_nome === true,
      mensagem_para_usuario: dados.mensagem_para_usuario || ''
    }
  }
];

const resultados = $input.all().map(item => item.json);

let mensagem = '';

if (resultados.length === 0) {
  mensagem = 'Nenhum usuário foi encontrado com esse nome.';
} else if (resultados.length === 1) {
  const usuario = resultados[0];

  mensagem =
`Encontrei 1 usuário:

ID: ${usuario.id}
Nome: ${usuario.nome_completo}`;
} else {
  mensagem = `Encontrei ${resultados.length} usuários:\n\n`;

  mensagem += resultados
    .map((usuario, index) => {
      return `${index + 1}. ID: ${usuario.id}\nNome: ${usuario.nome_completo}`;
    })
    .join('\n\n');
}

return [
  {
    json: {
      quantidade_encontrada: resultados.length,
      usuarios: resultados,
      mensagem_evolution: mensagem
    }
  }
];

