let dados;

try {
  dados = JSON.parse(texto);
} catch (error) {
  return [
    {
      json: {
        erro: true,
        numped: 0,
        mensagem_para_usuario: 'Não foi possível interpretar a resposta da IA.',
        texto_original: texto,
        detalhe: error.message
      }
    }
  ];
}

return [
  {
    json: {
      erro: false,
      numped: Number(dados.numped) || 0,
      mensagem_para_usuario: dados.mensagem_para_usuario || ''
    }
  }
];

const registros = $input.all().map(item => item.json);

// Separa cada tipo de registro
const pedido = registros.find(r => r.TIPO === 'PEDIDO');
const itens = registros.filter(r => r.TIPO === 'ITEM');
const bloqueios = registros.filter(r => r.TIPO === 'BLOQUEIO');

// Validação
if (!pedido) {
  return [
    {
      json: {
        erro: true,
        mensagem: 'Não foi possível localizar os dados principais do pedido.'
      }
    }
  ];
}

// Formata moeda
const moeda = (valor) => {
  return Number(valor || 0).toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  });
};

// Formata quantidade
const quantidade = (valor) => {
  const numero = Number(valor || 0);

  if (Number.isInteger(numero)) {
    return numero.toString();
  }

  return numero.toLocaleString('pt-BR');
};

// ==============================
// CABEÇALHO
// ==============================

let mensagem = `📦 *PEDIDO ${pedido.NUMPED}*\n\n`;

mensagem += `👤 *Cliente:* ${pedido.CODCLI} - ${pedido.CLIENTE}\n`;
mensagem += `💰 *Valor da venda:* ${moeda(pedido.VLTOTAL)}\n`;
mensagem += `📌 *Posição:* ${pedido.POSICAO || 'Não informada'}\n`;

// ==============================
// ITENS
// ==============================

mensagem += `\n━━━━━━━━━━━━━━━━━━\n`;
mensagem += `🛒 *ITENS DO PEDIDO*\n`;
mensagem += `━━━━━━━━━━━━━━━━━━\n\n`;

if (itens.length > 0) {
  itens.forEach((item, index) => {
    mensagem += `${index + 1}. *${item.CODPROD}* - ${item.DESCRICAO}\n`;
    mensagem += `   📦 Quantidade: ${quantidade(item.QT)}\n`;
    mensagem += `   💵 Unitário: ${moeda(item.PVENDA)}\n`;
    mensagem += `   💰 Total item: ${moeda(item.VLTOTAL_ITEM)}\n\n`;
  });
} else {
  mensagem += `Nenhum item encontrado.\n\n`;
}

// ==============================
// BLOQUEIOS
// ==============================

mensagem += `━━━━━━━━━━━━━━━━━━\n`;
mensagem += `🚫 *MOTIVOS DE BLOQUEIO*\n`;
mensagem += `━━━━━━━━━━━━━━━━━━\n\n`;

if (bloqueios.length > 0) {
  bloqueios.forEach((bloqueio, index) => {
    mensagem += `${index + 1}. ${bloqueio.MOTIVO}\n\n`;
  });
} else {
  mensagem += `✅ Nenhum bloqueio encontrado para este pedido.\n`;
}

// ==============================
// RETORNO
// ==============================

return [
  {
    json: {
      erro: false,
      numped: pedido.NUMPED,
      codcli: pedido.CODCLI,
      cliente: pedido.CLIENTE,
      vltotal: pedido.VLTOTAL,
      posicao: pedido.POSICAO,

      quantidade_itens: itens.length,
      quantidade_bloqueios: bloqueios.length,

      itens: itens.map(item => ({
        codprod: item.CODPROD,
        descricao: item.DESCRICAO,
        qt: item.QT,
        pvenda: item.PVENDA,
        vltotal_item: item.VLTOTAL_ITEM
      })),

      bloqueios: bloqueios.map(item => ({
        motivo: item.MOTIVO
      })),

      mensagem: mensagem.trim()
    }
  }
];

