const texto = $json.output?.[0]?.content?.find(
  item => item.type === 'output_text'
)?.text;

if (!texto) {
  throw new Error('Não foi possível localizar a resposta do modelo.');
}

let dados;

try {
  dados = JSON.parse(texto);
} catch (error) {
  throw new Error(`Resposta da IA não é um JSON válido: ${texto}`);
}

const produtos = Array.isArray(dados.produtos)
  ? dados.produtos
      .map(Number)
      .filter(Number.isFinite)
  : [];

return {
  json: {
    dados_validos: dados.dados_validos === true,
    filial: Number(dados.filial) || 0,
    produtos: produtos,
    produtos_csv: produtos.join(','),
    quantidade_produtos: produtos.length,
    mensagem_para_usuario: dados.mensagem_para_usuario || ''
  }
};

const itens = $input.all();

if (!itens.length) {
  return [
    {
      json: {
        mensagem: '❌ Nenhum produto foi encontrado para a consulta.'
      }
    }
  ];
}

const filial = itens[0].json.FILIAL || '';
const codFilial = itens[0].json.CODFILIAL || '';

let mensagem = `📦 *Consulta de Estoque*\n\n`;

if (filial) {
  mensagem += `🏢 *Filial:* ${codFilial} - ${filial}\n`;
}

mensagem += `📋 *Produtos encontrados:* ${itens.length}\n\n`;

itens.forEach((item, index) => {
  const p = item.json;

  mensagem += `━━━━━━━━━━━━━━━━━━\n`;
  mensagem += `📦 *Produto ${index + 1}*\n\n`;

  mensagem += `🔢 *Código:* ${p.CODPROD ?? '-'}\n`;
  mensagem += `📝 *Descrição:* ${p.DESCRICAO ?? '-'}\n`;
  mensagem += `📏 *Unidade:* ${p.UNIDADE ?? '-'}\n\n`;

  mensagem += `📊 *Estoque*\n`;
  mensagem += `• Estoque geral: ${p.ESTOQUE_GERAL ?? 0}\n`;
  mensagem += `• Bloqueado: ${p.QTD_BLOQUEADA ?? 0}\n`;
  mensagem += `• Avaria: ${p.QTD_AVARIA ?? 0}\n`;
  mensagem += `• Pendente: ${p.QTD_PENDENTE ?? 0}\n`;
  mensagem += `• Reservado: ${p.QTD_RESERVADA ?? 0}\n`;
  mensagem += `• Indústria: ${p.QTD_INDUSTRIA ?? 0}\n`;
  mensagem += `• Pedido: ${p.QTD_PEDIDA ?? 0}\n`;
  mensagem += `• Trânsito: ${p.QTD_TRANSITO ?? 0}\n`;

  mensagem += `\n✅ *Disponível:* ${p.QTD_DISPONIVEL ?? 0}\n\n`;
});

return [
  {
    json: {
      quantidade_produtos: itens.length,
      filial: codFilial,
      nome_filial: filial,
      mensagem: mensagem.trim()
    }
  }
];
